SET client_encoding = 'UTF8';
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS region_types (
  type text PRIMARY KEY,
  description text NOT NULL
);

ON CONFLICT (type) DO UPDATE SET description = EXCLUDED.description;

CREATE TABLE IF NOT EXISTS regions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  parent_id bigint REFERENCES regions(id) ON UPDATE CASCADE ON DELETE RESTRICT,
  slug text NOT NULL UNIQUE CHECK (slug = lower(slug)),
  name_tm text NOT NULL,
  name_en text NOT NULL,
  name_ru text,
  type text NOT NULL REFERENCES region_types(type),
  latitude numeric(9,6) CHECK (latitude BETWEEN -90 AND 90),
  longitude numeric(9,6) CHECK (longitude BETWEEN -180 AND 180),
  country_code char(2) NOT NULL DEFAULT 'TM' CHECK (country_code = 'TM'),
  verification_status text NOT NULL DEFAULT 'verified'
    CHECK (verification_status IN ('verified', 'verification_required')),
  source_url text,
  source_date date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (parent_id IS NOT NULL OR type = 'country')
);

CREATE TABLE IF NOT EXISTS region_aliases (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  region_id bigint NOT NULL REFERENCES regions(id) ON UPDATE CASCADE ON DELETE CASCADE,
  alias text NOT NULL CHECK (btrim(alias) <> ''),
  language text NOT NULL CHECK (language IN ('tm', 'en', 'ru', 'und')),
  alias_type text NOT NULL CHECK (alias_type IN ('canonical', 'transliteration', 'ascii', 'historical', 'alternative')),
  normalized_alias text NOT NULL CHECK (normalized_alias = lower(normalized_alias)),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (region_id, alias)
);

CREATE OR REPLACE FUNCTION tm_normalize(value text)
RETURNS text LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
  SELECT trim(regexp_replace(translate(lower(value),
    'äçşňöüýžёÄÇŞŇÖÜÝŽЁ',
    'acsnouyzeACSNOUYZE'), '[^a-z0-9а-я]+', ' ', 'g'));
$$;

CREATE OR REPLACE VIEW region_search AS
SELECT r.id, r.parent_id, r.slug, r.name_tm AS canonical_name, r.type,
       a.alias, a.language, a.alias_type
FROM regions r
JOIN region_aliases a ON a.region_id = r.id;

CREATE OR REPLACE FUNCTION find_region(query text)
RETURNS TABLE (
  id bigint, parent_id bigint, slug text, canonical_name text, type text,
  alias text, language text, alias_type text, similarity real
) LANGUAGE sql STABLE AS $$
  WITH q AS (SELECT tm_normalize(query) AS value)
  SELECT rs.id, rs.parent_id, rs.slug, rs.canonical_name, rs.type,
         rs.alias, rs.language, rs.alias_type,
         similarity(tm_normalize(rs.alias), q.value) AS similarity
  FROM region_search rs CROSS JOIN q
  WHERE tm_normalize(rs.alias) = q.value
     OR tm_normalize(rs.alias) % q.value
  ORDER BY (tm_normalize(rs.alias) = q.value) DESC,
           similarity(tm_normalize(rs.alias), q.value) DESC,
           rs.type, rs.canonical_name;
$$;

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX IF NOT EXISTS regions_parent_id_idx ON regions(parent_id);
CREATE INDEX IF NOT EXISTS regions_type_idx ON regions(type);
CREATE INDEX IF NOT EXISTS regions_name_tm_lower_idx ON regions(lower(name_tm));
CREATE INDEX IF NOT EXISTS region_aliases_region_id_idx ON region_aliases(region_id);
CREATE INDEX IF NOT EXISTS region_aliases_normalized_idx ON region_aliases(normalized_alias);
CREATE UNIQUE INDEX IF NOT EXISTS region_aliases_region_alias_ci_uidx
  ON region_aliases(region_id, lower(alias));
CREATE INDEX IF NOT EXISTS region_aliases_normalized_trgm_idx
  ON region_aliases USING gin (normalized_alias gin_trgm_ops);
CREATE INDEX IF NOT EXISTS region_aliases_alias_trgm_idx
  ON region_aliases USING gin (tm_normalize(alias) gin_trgm_ops);

SET client_encoding = 'UTF8';
BEGIN;

CREATE TEMP TABLE region_seed (slug text PRIMARY KEY,parent_slug text,name_tm text,name_en text,name_ru text,type text,latitude numeric,longitude numeric,country_code char(2),verification_status text,source_url text,source_date date) ON COMMIT DROP;


ON CONFLICT (region_id,alias) DO UPDATE SET language=EXCLUDED.language,alias_type=EXCLUDED.alias_type,normalized_alias=EXCLUDED.normalized_alias;
COMMIT;
