INSERT INTO regions (slug,name_tm,name_en,name_ru,type,latitude,longitude,country_code,verification_status,source_url,source_date) SELECT slug,name_tm,name_en,name_ru,type,latitude,longitude,country_code,verification_status,source_url,source_date FROM region_seed WHERE parent_slug IS NULL ON CONFLICT (slug) DO UPDATE SET name_tm=EXCLUDED.name_tm,name_en=EXCLUDED.name_en,name_ru=EXCLUDED.name_ru,type=EXCLUDED.type,latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,verification_status=EXCLUDED.verification_status,source_url=EXCLUDED.source_url,source_date=EXCLUDED.source_date,updated_at=now();
